+    let status_ids = status["packages"]
+        .as_array()
+        .unwrap()
+        .iter()
+        .filter_map(|package| package["package"].as_str())
+        .collect::<Vec<_>>();
+    assert!(status_ids.contains(&"cargo/app"), "{status}");
