    let manifest_rel = rel_path.join(filename);
    let canonical_decl = ManifestDecl::new(manifest_rel.clone(), ManifestRole::Canonical, fmt).ok();
    if let Some(decl) = &canonical_decl {
        decls.push(decl.clone());
    }
