 432	
 433	        if has_project_version {
 434	            if let Some(proj) = self.document.get_mut("project").and_then(|p| p.as_table_like_mut()) {
 435	                crate::common::set_scalar_preserving_decor(proj, "version", new_ver);
 436	            }
 437	        } else if let Some(poetry) = self
 438	            .document
 439	            .get_mut("tool")
 440	            .and_then(|t| t.get_mut("poetry"))
 441	            .and_then(|p| p.as_table_like_mut())
 442	        {
 443	            crate::common::set_scalar_preserving_decor(poetry, "version", new_ver);
 444	        } else if let Some(flit) = self
 445	            .document
 446	            .get_mut("tool")
 447	            .and_then(|t| t.get_mut("flit"))
 448	            .and_then(|f| f.get_mut("metadata"))
 449	            .and_then(|m| m.as_table_like_mut())
 450	        {
 451	            crate::common::set_scalar_preserving_decor(flit, "version", new_ver);
 452	        } else {
 453	            self.document["project"]["version"] = value(new_ver);
 454	        }
 455	
 456	        Ok(())
 457	    }
