 642	    fn is_publishable(&self) -> bool {
 643	        // A pyproject.toml without [project].name or [tool.poetry].name is a
 644	        // workspace root or build-system-only file — not a publishable package.
 645	        let has_pep621_name = self
 646	            .document
 647	            .get("project")
 648	            .and_then(|p| p.get("name"))
 649	            .and_then(|n| n.as_str())
 650	            .is_some();
 651	        let has_poetry_name = self
 652	            .document
 653	            .get("tool")
 654	            .and_then(|t| t.get("poetry"))
 655	            .and_then(|p| p.get("name"))
 656	            .and_then(|n| n.as_str())
 657	            .is_some();
 658	        has_pep621_name || has_poetry_name
 659	    }
