 668	    fn update_optional_dependencies(
 669	        &mut self,
 670	        updates: &[(String, Version)],
 671	        _permit: &ApplyPermit,
 672	    ) -> Result<(), ManifestError> {
 673	        if updates.is_empty() {
 674	            return Ok(());
 675	        }
 676	
 677	        // [project.optional-dependencies] is a table of group_name → [PEP 508 strings].
 678	        // Collect the table keys first to avoid borrow conflicts.
 679	        let group_keys: Vec<String> = self
 680	            .document
 681	            .get("project")
 682	            .and_then(|p| p.get("optional-dependencies"))
 683	            .and_then(|od| od.as_table_like())
 684	            .map(|t| t.iter().map(|(k, _)| k.to_string()).collect())
 685	            .unwrap_or_default();
 686	
 687	        for group_key in &group_keys {
 688	            let Some(arr) = self
 689	                .document
 690	                .get_mut("project")
 691	                .and_then(|p| p.get_mut("optional-dependencies"))
 692	                .and_then(|od| od.get_mut(group_key.as_str()))
 693	                .and_then(|g| g.as_array_mut())
 694	            else {
 695	                continue;
 696	            };
 697	
 698	            for idx in 0..arr.len() {
 699	                let Some(full_req) = arr.get(idx).and_then(|item| item.as_str()) else {
 700	                    continue;
 701	                };
 702	                let Some(req) = Requirement::parse(full_req) else {
 703	                    continue;
 704	                };
 705	
 706	                if let Some((_dep_name, new_ver)) = updates.iter().find(|(dep_name, _)| {
 707	                    normalize_pypi_package_name(dep_name) == normalize_pypi_package_name(&req.name)
 708	                }) {
 709	                    let new_req = Requirement {
 710	                        name: req.name.clone(),
 711	                        extras: req.extras.clone(),
 712	                        spec: Some(format!(">={}", new_ver.render())),
 713	                        marker: req.marker.clone(),
 714	                    };
 715	                    arr.replace(idx, new_req.render());
 716	                }
 717	            }
 718	        }
 719	
 720	        Ok(())
 721	    }
 722	}
