 459	    fn iter_dependencies(&self) -> Box<dyn Iterator<Item = DependencyEntry> + '_> {
 460	        let mut entries = Vec::new();
 461	
 462	        // 1. PEP 621 [project].dependencies (array of requirement strings)
 463	        if let Some(deps) = self
 464	            .document
 465	            .get("project")
 466	            .and_then(|p| p.get("dependencies"))
 467	            .and_then(|d| d.as_array())
 468	        {
 469	            for item in deps {
 470	                if let Some(full_req_str) = item.as_str() {
 471	                    if let Some(req) = Requirement::parse(full_req_str) {
 472	                        let req_str = req.spec.clone().unwrap_or_else(|| "*".to_string());
 473	                        let parsed_req_str = req.spec.as_deref().unwrap_or(">=0.0.0");
 474	                        let spec = match VersionReq::parse(parsed_req_str, Ecosystem::Pypi) {
 475	                            Ok(spec) => DepSpec::Range(spec, req_str),
 476	                            // A PEP 508 clause `pep440_rs` can't parse (exotic
 477	                            // or malformed syntax) -- keep the dependency
 478	                            // visible in the graph rather than silently
 479	                            // dropping it.
 480	                            Err(_) => DepSpec::Opaque(req_str),
 481	                        };
 482	                        entries.push(DependencyEntry {
 483	                            name: req.name.clone(),
 484	                            package_name: req.name.clone(),
 485	                            inherited: false,
 486	                            kind: DepKind::Runtime,
 487	                            spec,
 488	                        });
 489	                    }
 490	                    // else: `Requirement::parse` couldn't extract even a
 491	                    // package name (e.g. an empty string or a marker-only
 492	                    // fragment) -- there's no name to key a `DependencyEntry`
 493	                    // on, so this genuinely can't be represented.
 494	                }
 495	            }
 496	        }
 497	
 498	        // 2. Poetry [tool.poetry.dependencies]
 499	        if let Some(table) = self
 500	            .document
 501	            .get("tool")
 502	            .and_then(|t| t.get("poetry"))
 503	            .and_then(|p| p.get("dependencies"))
 504	            .and_then(|d| d.as_table_like())
 505	        {
 506	            for (name, item) in table.iter() {
 507	                if name == "python" {
 508	                    continue;
 509	                }
 510	                // `as_table_like()` covers both inline tables
 511	                // (`foo = { version = "^1.2" }`) and dotted-table syntax
 512	                // (`[tool.poetry.dependencies.foo]` / `version = "^1.2"`),
 513	                // which parse to different `toml_edit::Item` variants but
 514	                // must both be recognized -- previously only the inline-table
 515	                // variant was handled, so a dotted-table Poetry dependency
 516	                // silently vanished from the graph entirely.
 517	                let raw_req = match item {
 518	                    toml_edit::Item::Value(toml_edit::Value::String(s)) => Some(s.value().as_str()),
 519	                    _ => item
 520	                        .as_table_like()
 521	                        .and_then(|t| t.get("version"))
 522	                        .and_then(|v| v.as_str()),
 523	                };
 524	
 525	                let spec = match raw_req {
 526	                    Some(req_str) => {
 527	                        // Poetry allows caret/tilde/wildcard syntax on top of
 528	                        // PEP 440 (e.g. `^1.2`, `~1.2.3`, `1.*`), which
 529	                        // `pep440_rs` cannot parse directly -- normalize it
 530	                        // to an equivalent PEP 440 range first.
 531	                        let normalized = normalize_poetry_version_spec(req_str);
 532	                        match VersionReq::parse(&normalized, Ecosystem::Pypi) {
 533	                            Ok(spec) => DepSpec::Range(spec, req_str.to_string()),
 534	                            // Genuinely unrepresentable (syntax this
 535	                            // normalizer doesn't cover) -- never silently
 536	                            // drop the dependency; keep it visible in the
 537	                            // graph as an opaque spec instead.
 538	                            Err(_) => DepSpec::Opaque(req_str.to_string()),
 539	                        }
 540	                    }
 541	                    // No `version` key at all -- a path/git/url dependency
 542	                    // (e.g. `foo = { git = "...", tag = "v1.0" }`) or an
 543	                    // unrecognized value shape. Still must not silently
 544	                    // vanish from the graph.
 545	                    None => {
 546	                        DepSpec::Opaque("non-versioned dependency (path/git/url or unrecognized shape)".to_string())
 547	                    }
 548	                };
 549	
 550	                entries.push(DependencyEntry {
 551	                    name: name.to_string(),
 552	                    package_name: name.to_string(),
 553	                    inherited: false,
 554	                    kind: DepKind::Runtime,
 555	                    spec,
 556	                });
 557	            }
 558	        }
 559	
 560	        Box::new(entries.into_iter())
 561	    }
