 724	/// Rewrites a PEP 508 dependency constraint to pin it to `target`.
 725	///
 726	/// The following single-clause and two-clause forms are recognized and rewritten:
 727	///
 728	/// - `==X.Y.Z` — exact pin — is rewritten to `==NEW`.
 729	/// - `~=X.Y.Z` — compatible release — is rewritten to `~=NEW`.
 730	/// - `>=X.Y.Z` — lower bound only — is rewritten to `>=NEW`.
 731	/// - `>=X.Y.Z,<A.B` — two-clause range — is rewritten to `>=NEW,<NEXT_MAJOR`
 732	///   where `NEXT_MAJOR` equals `target.major() + 1`.
 733	///
 734	/// A pre-release or dev/local target (e.g. a `snapshot` version) is rendered
 735	/// in full rather than truncated to `major.minor.patch`, the same precision
 736	/// rule `cargo::round_trip` applies for SemVer.
 737	///
 738	/// All other forms return `None` — including upper-bound-only (`<`, `<=`),
 739	/// exclusion (`!=`), compound expressions beyond the two-clause range above,
 740	/// and wildcard `*`. Callers must leave the original constraint unchanged
 741	/// when `None` is returned.
 742	pub fn round_trip(spec: &DepSpec, target: &Version) -> Option<DepSpec> {
 743	    // Only Range specs are produced by iter_dependencies for Python.
 744	    let original = match spec {
 745	        DepSpec::Range(_, raw) => raw.as_str(),
 746	        _ => return None,
 747	    };
 748	
 749	    let trimmed = original.trim();
 750	
 751	    // Compound range: ">=X.Y.Z,<A.B" → ">=NEW,<NEXT_MAJOR"
 752	    if trimmed.contains(',') {
 753	        return rewrite_range(trimmed, target);
 754	    }
 755	
 756	    // Single-clause forms matched by their PEP 508 operator prefix.
 757	    if trimmed.starts_with("==") {
 758	        return rewrite_single(trimmed, "==", target);
 759	    }
 760	    if trimmed.starts_with("~=") {
 761	        return rewrite_single(trimmed, "~=", target);
 762	    }
 763	    if trimmed.starts_with(">=") {
 764	        return rewrite_single(trimmed, ">=", target);
 765	    }
 766	
 767	    // Unknown or unsupported form (e.g. "<", "<=", "!=", bare "*").
 768	    None
 769	}
 770	
 771	/// Rewrites a single-clause PEP 508 specifier, preserving the operator.
 772	fn rewrite_single(original: &str, op: &str, target: &Version) -> Option<DepSpec> {
 773	    // Validate that the original clause parses correctly (guards against
 774	    // unknown version syntax that happens to start with a known prefix).
 775	    let _rest = original.strip_prefix(op)?;
 776	    let rendered = format!("{op}{}", render_target(op, target)?);
 777	    let req = VersionReq::parse(&rendered, Ecosystem::Pypi).ok()?;
 778	    Some(DepSpec::Range(req, rendered))
 779	}
 780	
 781	/// Renders `target` at the precision a rewritten spec should carry, for use after `op`:
 782	/// `major.minor.patch` for a stable release; the version in full for a pre-release or
 783	/// dev target paired with `==`/`!=` (the only operators PEP 440 allows on a local version);
 784	/// the version with its local segment stripped for every other operator, since PEP 440
 785	/// forbids `>=`, `<=`, `>`, `<` and `~=` from carrying one.
 786	fn render_target(op: &str, target: &Version) -> Option<String> {
 787	    if target.is_prerelease() {
 788	        let full = target.render();
 789	        if op == "==" || op == "!=" {
 790	            return Some(full.to_string());
 791	        }
 792	        return Some(full.split('+').next().unwrap_or(full).to_string());
 793	    }
 794	    Some(format!("{}.{}.{}", target.major()?, target.minor()?, target.patch()?))
 795	}
 796	
 797	/// Rewrites a two-clause `>=X.Y.Z,<A.B` range to `>=NEW,<NEXT_MAJOR`.
 798	///
 799	/// Returns `None` for anything that does not match exactly this two-clause
 800	/// lower/upper pattern, including specs with three or more clauses (e.g.
 801	/// `>=1.0,<2.0,!=1.5.0`) where silently dropping extra clauses would produce
 802	/// a semantically incorrect constraint.
 803	fn rewrite_range(original: &str, target: &Version) -> Option<DepSpec> {
 804	    // Reject any spec with more than two comma-separated clauses: rewriting
 805	    // would silently discard the extra clauses, changing the semantics.
 806	    if original.split(',').count() != 2 {
 807	        return None;
 808	    }
 809	
 810	    let mut parts = original.splitn(2, ',');
 811	    let lower = parts.next()?.trim();
 812	    let upper = parts.next()?.trim();
 813	
 814	    // Lower clause must be `>=…`.
 815	    if !lower.starts_with(">=") {
 816	        return None;
 817	    }
 818	    // Upper clause must be strictly `<…` (not `<=`).
 819	    if !upper.starts_with('<') || upper.starts_with("<=") {
 820	        return None;
 821	    }
 822	
 823	    let next_major = target.major()? + 1;
 824	    let rendered = format!(">={},<{next_major}", render_target(">=", target)?);
 825	    let req = VersionReq::parse(&rendered, Ecosystem::Pypi).ok()?;
 826	    Some(DepSpec::Range(req, rendered))
 827	}
