+
+    let output = Command::new(env!("CARGO_BIN_EXE_callisto"))
+        .args([
+            "--format",
+            "json",
+            "--cwd",
+            root.to_str().unwrap(),
+            "snapshot",
+            "--tag",
+            "canary",
+        ])
+        .output()
+        .unwrap();
+    assert!(
