+            if name == "inline_alias" { "^1.0" } else { "~1.0" }
+        );
+    }
+
+    let permit = ApplyPermit::force_for_tests();
+    for entry in &entries {
+        manifest
+            .update_dependency_spec(
+                &entry.name,
+                entry.kind,
+                DepSpec::CargoBare(Version::semver(2, 0, 0)),
+                &permit,
+            )
+            .unwrap();
